const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const peoria = ee.Geometry.Point([-89.5889, 40.6936]); // Peoria, IL coordinates
  const region = peoria.buffer(20000); // 20km buffer around Peoria

  const sept2022 = ee.DateRange('2022-09-01', '2022-09-30');
  const oct2022 = ee.DateRange('2022-10-01', '2022-10-31');

  // 2. Data Acquisition
  function getSentinel2Collection(dateRange) {
    return ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(region)
      .filterDate(dateRange)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));
  }

  const septCol = getSentinel2Collection(sept2022);
  const octCol = getSentinel2Collection(oct2022);

  const septSize = septCol.size().getInfo();
  const octSize = octCol.size().getInfo();

  console.log(`Sept 2022 Images: ${septSize}`);
  console.log(`Oct 2022 Images: ${octSize}`);

  // Check for empty collections
  if (septSize === 0 || octSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Cloud mask and NDVI calculation
  function maskClouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                 .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  function addNDVI(image) {
    const ndvi = image.normalizedDifference(['B8', 'B4']).rename('NDVI');
    return image.addBands(ndvi);
  }

  // Process collections
  const septProcessed = septCol.map(maskClouds).map(addNDVI).median();
  const octProcessed = octCol.map(maskClouds).map(addNDVI).median();

  // 4. Calculate statistics
  const septStats = septProcessed.select('NDVI').reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  });

  const octStats = octProcessed.select('NDVI').reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  });

  const septMean = septStats.get('NDVI_mean').getInfo();
  const septCount = septStats.get('NDVI_count').getInfo();
  const octMean = octStats.get('NDVI_mean').getInfo();
  const octCount = octStats.get('NDVI_count').getInfo();

  console.log(`Sept NDVI: ${septMean?.toFixed(4)}, Pixels: ${septCount}`);
  console.log(`Oct NDVI: ${octMean?.toFixed(4)}, Pixels: ${octCount}`);

  // 5. Validation & Final Answer
  if (septCount === 0 || octCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  if (septMean === null || octMean === null || 
      isNaN(septMean) || isNaN(octMean) ||
      septMean < -1 || septMean > 1 || octMean < -1 || octMean > 1) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Lower NDVI = more brown fields
  if (octMean < septMean) {
    console.log("<answer>A</answer>"); // Yes, more brown in October
  } else {
    console.log("<answer>B</answer>"); // No, not more brown in October
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
